"""Pure-lazy lexical and transitive purity, with ordered taint and visitor pruning."""
import re
from data_layer_six.common import A,O,K,P,E,S,q,literals,choice
from data_layer_generate_batch_seven import constant
from data_layer_eight.relations import clause
from data_layer_eight.model import stages as model


def candidate(source,policy):
    module=source/'scripts/lint_pure_lazy_runtime_purity.py';value=lambda n:constant(module,n)
    p=policy('pure_lazy_runtime_purity',['impl/**/*.py','data_layer/**/*.py','_internal/**/*.py','l[0-9][0-9][0-9][0-9]_*/**/*.py'])
    p['clauses'].append({'id':'entry','define':{'options':{'oracleAnalyzer':{'type':'boolean','default':False},'entryPoint':{'type':'string','default':'scan_paths'},'primaryPaths':{'type':'array','items':'string','default':[]}}}})
    protected=literals(value('PROTECTED_RUNTIME_ATTRS'));handles=literals(value('RUNTIME_HANDLE_TYPE_NAMES'));helpers=literals(value('PURE_SURFACE_HELPER_CALLS'));opaque=literals(value('OPAQUE_PURE_LAZY_HELPER_CALLS'))
    stages=[*model(),
      S('primary_paths',{'$option':'primaryPaths','escape':'sql','map':' UNION ALL SELECT {} path','join':'','template':"SELECT '' path WHERE 0{}"},('path',)),
      S('function_flags',"""SELECT f.*,EXISTS(SELECT 1 FROM decorator_names d WHERE d.__path=f.__path AND d.fn=f.id AND d.name IN ('pure_lazy','lazy')) explicit,
        EXISTS(SELECT 1 FROM decorator_names d WHERE d.__path=f.__path AND d.fn=f.id AND d.name IN ('legacy_sync','legacy_async','legacy_module_sync','legacy_module_async')) legacy,
        EXISTS(SELECT 1 FROM ownership o JOIN classes c ON c.__path=o.__path AND c.id=o.cls JOIN assignments a ON a.__path=c.__path JOIN nodes parent ON parent.__path=a.__path AND parent.id=a.parent WHERE o.__path=f.__path AND o.id=f.id AND a.target_kind='identifier' AND a.target_text='__pure_lazy_surface__' AND a.expr_kind='true' AND parent.parent=c.body_kind||':'||c.body_start||':'||c.body_end) surface
        FROM declaration_contexts f WHERE f.kind='function_definition'""",('__path','id')),
      S('colored_functions',"""WITH RECURSIVE colored(__path,id,color) AS (
        SELECT __path,id,'pure' FROM function_flags WHERE explicit
        UNION SELECT f.__path,f.id,'owner' FROM function_flags f WHERE f.name GLOB '*_lazy' AND EXISTS(SELECT 1 FROM parameters p WHERE p.__path=f.__path AND p.fn=f.id AND p.name IN """+literals(value('RUNTIME_OWNER_PARAM_NAMES'))+") AND EXISTS(SELECT 1 FROM calls c WHERE c.__path=f.__path AND c.__start>=f.body_start AND c.__end<=f.body_end AND c.callee IN "+literals(value('PLAN_HELPER_TERMINAL_NAMES'))+") UNION SELECT e.target_path,e.target,c.color FROM colored c JOIN purity_call_edges e ON e.__path=c.__path AND e.caller=c.id JOIN function_flags f ON f.__path=e.target_path AND f.id=e.target WHERE NOT f.legacy) SELECT __path,id,max(color) color FROM colored GROUP BY __path,id",('__path','id')),
      S('active_functions',{'$option':'entryPoint','cases':{'scan_source':"SELECT f.*,0 strict,'pure' color FROM function_flags f WHERE EXISTS(SELECT 1 FROM function_flags a WHERE a.__path=f.__path AND a.region_start<=f.region_start AND a.__end>=f.__end AND EXISTS(SELECT 1 FROM decorator_names d WHERE d.__path=a.__path AND d.fn=a.id AND d.name='pure_lazy')) AND NOT rx_matches(f.__path,'/tests/') AND EXISTS(SELECT 1 FROM nodes n WHERE n.__path=f.__path AND n.kind='module' AND rx_matches(n.text,'pure_lazy|@lazy|__pure_lazy_surface__'))"},'default':"SELECT f.*,NOT f.explicit strict,c.color FROM function_flags f JOIN colored_functions c ON c.__path=f.__path AND c.id=f.id WHERE NOT EXISTS(SELECT 1 FROM primary_paths) OR f.__path IN (SELECT path FROM primary_paths)"},('__path','id')),
      S('body_nodes',"SELECT f.__path,f.id fn,n.id,n.__start,n.__end,n.kind,n.text FROM active_functions f JOIN nodes n ON n.__path=f.__path AND n.__start>=f.body_start AND n.__end<=f.body_end",('__path','fn','id')),
      S('return_contracts',"""SELECT DISTINCT f.__path,f.id FROM functions f JOIN nodes a ON a.__path=f.__path AND a.__start>=f.return_type_start AND a.__end<=f.return_type_end WHERE a.kind IN ('identifier','attribute') AND coalesce(a.attribute_source,a.text) IN """+handles+" AND NOT EXISTS(SELECT 1 FROM nodes wrapper WHERE wrapper.__path=a.__path AND wrapper.kind IN ('generic_type','subscript') AND wrapper.__start>=f.return_type_start AND wrapper.__start<a.__start AND wrapper.__end>=a.__end AND rx_matches(wrapper.text,'^(?:type|Type)\\s*\\['))",('__path','id')),
      S('passthrough',"SELECT c.__path,c.id,coalesce(a.id,c.id) value FROM calls c LEFT JOIN arguments a ON a.__path=c.__path AND a.call=c.id AND a.position=1 AND c.callee_kind='identifier' AND c.callee='cast' AND (SELECT count(*) FROM arguments x WHERE x.__path=c.__path AND x.call=c.id)=2",('__path','id')),
      S('module_bindings',"SELECT a.*,b.name FROM assignments a JOIN bound_names b ON b.__path=a.__path AND b.assignment=a.id JOIN nodes e ON e.__path=a.__path AND e.id=a.parent JOIN nodes parent ON parent.__path=e.__path AND parent.id=e.parent WHERE e.kind='expression_statement' AND parent.kind='module'",('__path','name')),
      S('contextvars',"SELECT a.__path,a.name FROM module_bindings a JOIN calls c ON c.__path=a.__path AND c.id=a.value WHERE c.callee='ContextVar'",('__path','name')),
      S('runtime_sources',"""WITH RECURSIVE runtime(__path,id,name) AS (
        SELECT f.__path,f.id,f.name FROM functions f JOIN return_contracts r ON r.__path=f.__path AND r.id=f.id
        UNION SELECT f.__path,f.id,f.name FROM functions f JOIN returns r ON r.__path=f.__path AND r.fn=f.id LEFT JOIN passthrough pass ON pass.__path=r.__path AND pass.id=r.value JOIN calls c ON c.__path=r.__path AND c.id=coalesce(pass.value,r.value) JOIN expression_roots root ON root.__path=c.__path AND root.expression=c.callee_id JOIN contextvars v ON v.__path=root.__path AND v.name=root.name WHERE c.callee='get'
        UNION SELECT f.__path,f.id,f.name FROM functions f JOIN returns r ON r.__path=f.__path AND r.fn=f.id JOIN calls c ON c.__path=r.__path AND c.id=r.value JOIN runtime old ON old.__path=c.__path AND old.name=c.callee) SELECT * FROM runtime""",('__path','name')),
      S('runtime_calls',"SELECT c.__path,c.id FROM calls c JOIN expression_roots root ON root.__path=c.__path AND root.expression=c.callee_id WHERE c.callee='get' AND EXISTS(SELECT 1 FROM contextvars v WHERE v.__path=c.__path AND v.name=root.name) OR EXISTS(SELECT 1 FROM runtime_sources h WHERE h.__path=c.__path AND h.name=c.callee AND (c.callee_kind='identifier' OR root.name IN ('self','cls')))",('__path','id')),
      S('opaque_calls',"SELECT DISTINCT c.__path,c.id FROM calls c WHERE c.callee IN "+opaque+" OR c.callee='LazyOperation' AND EXISTS(SELECT 1 FROM keywords k JOIN calls payload ON payload.__path=k.__path AND payload.id=k.value JOIN keywords field ON field.__path=payload.__path AND field.call=payload.id WHERE k.__path=c.__path AND k.call=c.id AND k.name='payload' AND field.name IN "+literals(value('OPAQUE_LAZY_OPERATION_PAYLOAD_FIELDS'))+")",('__path','id')),
      S('opaque_locals',"""WITH RECURSIVE opaque_local(__path,fn,name,since) AS (
        SELECT a.__path,a.fn,b.name,a.__start FROM assignments a JOIN bound_names b ON b.__path=a.__path AND b.assignment=a.id LEFT JOIN passthrough pass ON pass.__path=a.__path AND pass.id=a.value JOIN opaque_calls o ON o.__path=a.__path AND o.id=coalesce(pass.value,a.value)
        UNION SELECT a.__path,a.fn,b.name,a.__start FROM assignments a JOIN bound_names b ON b.__path=a.__path AND b.assignment=a.id JOIN opaque_local old ON old.__path=a.__path AND old.fn=a.fn AND old.name=a.expr_text AND old.since<a.__start WHERE a.expr_kind='identifier') SELECT * FROM opaque_local""",('__path','fn','name','since')),
      S('opaque_values',"SELECT __path,id FROM opaque_calls UNION SELECT n.__path,n.id FROM nodes n JOIN ownership owner ON owner.__path=n.__path AND owner.id=n.id JOIN opaque_locals o ON o.__path=n.__path AND o.fn=owner.fn AND o.name=n.text AND o.since<n.__start WHERE n.kind='identifier' UNION SELECT c.__path,c.id FROM calls c JOIN arguments a ON a.__path=c.__path AND a.call=c.id AND a.position=0 JOIN opaque_locals o ON o.__path=a.__path AND o.name=a.text AND o.since<c.__start JOIN ownership owner ON owner.__path=c.__path AND owner.id=c.id AND owner.fn=o.fn WHERE c.callee IN ('queue_single','queue_sequence') AND a.kind='identifier'",('__path','id')),
      S('tainted_locals',"""WITH RECURSIVE taint(__path,fn,name,since) AS (
        SELECT a.__path,f.id,b.name,a.__start FROM active_functions f JOIN assignments a ON a.__path=f.__path AND a.__start>=f.body_start AND a.__end<=f.body_end JOIN bound_names b ON b.__path=a.__path AND b.assignment=a.id WHERE EXISTS(SELECT 1 FROM attributes attr JOIN expression_roots root ON root.__path=attr.__path AND root.expression=attr.object JOIN parameters p ON p.__path=root.__path AND p.fn=f.id AND p.name=root.name WHERE attr.__path=a.__path AND attr.__start>=a.right_start AND attr.__end<=a.right_end AND attr.attr IN """+protected+" AND NOT (f.surface AND root.name='self')) OR EXISTS(SELECT 1 FROM runtime_calls r WHERE r.__path=a.__path AND r.id=a.value) OR EXISTS(SELECT 1 FROM opaque_values r WHERE r.__path=a.__path AND r.id=a.value)\n UNION SELECT a.__path,f.id,b.name,a.__start FROM taint t JOIN active_functions f ON f.__path=t.__path AND f.id=t.fn JOIN assignments a ON a.__path=f.__path AND a.__start>=f.body_start AND a.__end<=f.body_end AND a.__start>t.since JOIN bound_names b ON b.__path=a.__path AND b.assignment=a.id JOIN nodes n ON n.__path=a.__path AND n.__start>=a.right_start AND n.__end<=a.right_end AND n.kind='identifier' AND n.text=t.name) SELECT * FROM taint",('__path','fn','name','since')),
      S('protected_accesses',"SELECT f.__path,f.id fn,a.id,a.__start,a.__end,a.attr detail,r.through_call FROM active_functions f JOIN attributes a ON a.__path=f.__path AND a.__start>=f.body_start AND a.__end<=f.body_end JOIN expression_roots r ON r.__path=a.__path AND r.expression=a.object WHERE a.attr IN "+protected+" AND NOT (f.surface AND r.name='self') AND (EXISTS(SELECT 1 FROM parameters p WHERE p.__path=f.__path AND p.fn=f.id AND p.name=r.name) OR EXISTS(SELECT 1 FROM tainted_locals t WHERE t.__path=f.__path AND t.fn=f.id AND t.name=r.name AND t.since<a.__start))",('__path','fn')),
      S('dynamic_accesses',"SELECT f.__path,f.id fn,c.id,c.__start,c.__end,s.value detail FROM active_functions f JOIN calls c ON c.__path=f.__path AND c.__start>=f.body_start AND c.__end<=f.body_end JOIN arguments first ON first.__path=c.__path AND first.call=c.id AND first.position=0 JOIN arguments second ON second.__path=c.__path AND second.call=c.id AND second.position=1 JOIN strings s ON s.__path=second.__path AND s.__start=second.__start JOIN expression_roots root ON root.__path=first.__path AND root.expression=first.id WHERE c.callee_kind='identifier' AND c.callee='getattr' AND s.value IN "+protected+" AND (f.strict OR NOT (f.surface AND root.name='self') AND (EXISTS(SELECT 1 FROM parameters p WHERE p.__path=f.__path AND p.fn=f.id AND p.name=root.name) OR EXISTS(SELECT 1 FROM tainted_locals t WHERE t.__path=f.__path AND t.fn=f.id AND t.name=root.name AND t.since<c.__start)))",('__path','fn','id')),
      S('frozen_classes',"SELECT DISTINCT c.__path,c.name FROM classes c JOIN decorator_names d ON d.__path=c.__path AND d.fn=c.id JOIN calls call ON call.__path=d.__path AND call.parent=d.decorator JOIN keywords k ON k.__path=call.__path AND k.call=call.id WHERE d.name='dataclass' AND k.name='frozen' AND k.kind='true'",('__path','name')),
      S('global_calls',"SELECT c.*,EXISTS(SELECT 1 FROM keywords k WHERE k.__path=c.__path AND k.call=c.id AND k.name='name') AND NOT EXISTS(SELECT 1 FROM keywords k WHERE k.__path=c.__path AND k.call=c.id AND k.name='register_with_manager' AND k.kind='false') AND (c.callee='ObjectCache' AND EXISTS(SELECT 1 FROM keywords k WHERE k.__path=c.__path AND k.call=c.id AND k.name='max_entries' AND k.kind!='none') OR c.callee IN ('LocalMetadataCache','WeakLocalMetadataCache') AND EXISTS(SELECT 1 FROM keywords k WHERE k.__path=c.__path AND k.call=c.id AND (k.name='max_entries' AND k.kind!='none' OR k.name='invalidation_policy' AND k.kind IN ('identifier','attribute') AND coalesce((SELECT a.attr FROM attributes a WHERE a.__path=k.__path AND a.id=k.value),k.text)!='MANUAL')) OR c.callee='IdentityTokenCache' AND EXISTS(SELECT 1 FROM keywords k WHERE k.__path=c.__path AND k.call=c.id AND k.name='max_strong_entries' AND k.kind!='none') AND EXISTS(SELECT 1 FROM keywords k JOIN attributes a ON a.__path=k.__path AND a.id=k.value WHERE k.__path=c.__path AND k.call=c.id AND k.name='invalidation_policy' AND a.attr='BOUNDED_IDENTITY_TOKENS')) managed FROM calls c",('__path','id')),
      S('mutated_globals',"SELECT DISTINCT b.__path,b.name FROM module_bindings b JOIN calls c ON c.__path=b.__path JOIN nodes r ON r.__path=c.__path AND r.id=c.receiver WHERE c.callee IN "+literals(value('MUTATING_METHOD_NAMES'))+" AND r.kind='identifier' AND r.text=b.name UNION SELECT DISTINCT b.__path,b.name FROM module_bindings b JOIN assignments a ON a.__path=b.__path JOIN nodes target ON target.__path=a.__path AND target.id=a.target JOIN expression_roots root ON root.__path=target.__path AND root.expression=target.id WHERE target.kind IN ('subscript','attribute') AND root.name=b.name",('__path','name')),
      S('global_state',"SELECT a.__path,a.name,CASE WHEN m.name IS NOT NULL OR a.expr_kind IN ('dictionary','dictionary_comprehension','list','list_comprehension','set','set_comprehension','generator_expression') THEN 1 ELSE 0 END mutable,coalesce(c.managed,0) managed FROM module_bindings a LEFT JOIN global_calls c ON c.__path=a.__path AND c.id=a.value LEFT JOIN mutated_globals m ON m.__path=a.__path AND m.name=a.name WHERE m.name IS NOT NULL OR a.expr_kind IN ('dictionary','dictionary_comprehension','list','list_comprehension','set','set_comprehension','generator_expression') OR c.id IS NOT NULL AND c.callee NOT IN "+literals(set(value('IMMUTABLE_GLOBAL_CALLS'))|set(value('TYPE_ONLY_GLOBAL_CALLS'))|{'load_python_module'})+" AND NOT (c.callee='compile' AND rx_matches(c.full_callee,'^(?:re|_re)\\.') OR c.callee='getLogger' AND c.callee_kind='attribute') AND NOT EXISTS(SELECT 1 FROM frozen_classes f WHERE f.__path=c.__path AND f.name=c.callee)",('__path','name')),
      S('global_uses',"SELECT f.__path,f.id fn,n.id,n.__start,n.__end,n.text name,g.mutable,g.managed FROM active_functions f JOIN nodes n ON n.__path=f.__path AND n.__start>=f.body_start AND n.__end<=f.body_end JOIN global_state g ON g.__path=n.__path AND g.name=n.text LEFT JOIN nodes parent ON parent.__path=n.__path AND parent.id=n.parent WHERE n.kind='identifier' AND NOT coalesce((parent.kind IN ('attribute','keyword_argument','function_definition','class_definition','default_parameter','typed_parameter','typed_default_parameter') AND n.id=parent.name_kind||':'||parent.name_start||':'||parent.name_end OR parent.kind='attribute' AND n.id=parent.attribute_kind||':'||parent.attribute_start||':'||parent.attribute_end),0) AND NOT EXISTS(SELECT 1 FROM parameters p WHERE p.__path=f.__path AND p.fn=f.id AND p.name=n.text) AND NOT EXISTS(SELECT 1 FROM assignments a JOIN bound_names b ON b.__path=a.__path AND b.assignment=a.id WHERE a.__path=f.__path AND a.fn=f.id AND b.name=n.text)",('__path','fn','id')),
      S('global_receivers',"SELECT f.__path,f.id fn,n.id,g.name,g.mutable,g.managed FROM active_functions f JOIN nodes n ON n.__path=f.__path AND n.__start>=f.body_start AND n.__end<=f.body_end JOIN expression_roots r ON r.__path=n.__path AND r.expression=n.id JOIN global_state g ON g.__path=r.__path AND g.name=r.name WHERE NOT r.through_call AND NOT EXISTS(SELECT 1 FROM parameters p WHERE p.__path=f.__path AND p.fn=f.id AND p.name=g.name) AND NOT EXISTS(SELECT 1 FROM assignments a JOIN bound_names b ON b.__path=a.__path AND b.assignment=a.id WHERE a.__path=f.__path AND a.fn=f.id AND b.name=g.name)",('__path','fn','id')),
      S('return_events',"""SELECT f.__path,f.id fn,r.id,r.__start,r.__end,
        CASE WHEN allowed.id IS NOT NULL THEN NULL WHEN opaque.id IS NOT NULL THEN 'PLP-010' WHEN dynamic.id IS NOT NULL THEN 'PLP-002'
        WHEN contract.id IS NOT NULL AND runtime.id IS NOT NULL THEN 'PLP-003'
        WHEN EXISTS(SELECT 1 FROM protected_accesses a WHERE a.__path=f.__path AND a.fn=f.id AND a.__start>=v.__start AND a.__end<=v.__end) OR wrapper.id IS NOT NULL AND EXISTS(SELECT 1 FROM runtime_calls c JOIN nodes n ON n.__path=c.__path AND n.id=c.id WHERE c.__path=f.__path AND n.__start>=v.__start AND n.__end<=v.__end) THEN CASE WHEN wrapper.id IS NOT NULL THEN 'PLP-004' ELSE 'PLP-003' END
        WHEN EXISTS(SELECT 1 FROM tainted_locals t JOIN nodes n ON n.__path=t.__path AND n.kind='identifier' AND n.text=t.name AND n.__start>t.since WHERE t.__path=f.__path AND t.fn=f.id AND n.__start>=v.__start AND n.__end<=v.__end) THEN 'PLP-005'
        WHEN v.kind NOT IN ('call','subscript') AND EXISTS(SELECT 1 FROM global_uses g WHERE g.__path=f.__path AND g.fn=f.id AND g.__start>=v.__start AND g.__end<=v.__end) THEN 'PLP-008' END issue,
        coalesce(dynamic.detail,'return') detail,allowed.id IS NOT NULL allowed
        FROM active_functions f JOIN returns r ON r.__path=f.__path AND r.__start>=f.body_start AND r.__end<=f.body_end JOIN nodes v ON v.__path=r.__path AND v.id=r.value LEFT JOIN passthrough pass ON pass.__path=v.__path AND pass.id=v.id
        LEFT JOIN calls allowed ON allowed.__path=r.__path AND allowed.id=coalesce(pass.value,v.id) AND allowed.callee_kind='identifier' AND allowed.callee IN """+helpers+" LEFT JOIN opaque_values opaque ON opaque.__path=r.__path AND opaque.id=coalesce(pass.value,v.id) LEFT JOIN dynamic_accesses dynamic ON dynamic.__path=r.__path AND dynamic.fn=f.id AND dynamic.id=v.id LEFT JOIN return_contracts contract ON contract.__path=f.__path AND contract.id=f.id LEFT JOIN runtime_calls runtime ON runtime.__path=v.__path AND runtime.id=coalesce(pass.value,v.id) LEFT JOIN calls wrapper ON wrapper.__path=v.__path AND wrapper.id=v.id AND wrapper.callee IN ('of','from_value','resolved') AND rx_matches(wrapper.full_callee,'^(?:LazyResult|LazySeq)\\.')",('__path','fn','id')),
      S('call_events',"""SELECT f.__path,f.id fn,c.id,c.__start,c.__end,
        CASE WHEN c.callee_kind='identifier' AND c.callee IN """+helpers+" THEN NULL WHEN dynamic.id IS NOT NULL THEN 'PLP-002' WHEN EXISTS(SELECT 1 FROM keywords k JOIN global_uses g ON g.__path=k.__path AND g.fn=f.id AND g.__start>=k.__start AND g.__end<=k.__end WHERE k.__path=c.__path AND k.call=c.id AND k.name IN "+literals(set(value('PROTECTED_RUNTIME_ATTRS'))|{'conn','connection','context','cursor','session','txn','tx'})+") THEN 'PLP-008' WHEN global.name IS NOT NULL THEN CASE WHEN EXISTS(SELECT 1 FROM contextvars ctx WHERE ctx.__path=c.__path AND ctx.name=global.name) THEN 'PLP-008' WHEN NOT (global.managed AND '.'||c.callee IN "+literals(value('MANAGED_MEMOIZATION_CACHE_ACCESSES'))+") AND NOT (c.__path='l1000_cache/schema_generation.py' AND global.name='_callback_registry' AND c.callee IN ('contains','register','version')) THEN 'PLP-009' END END issue,\n        coalesce(dynamic.detail,global.name||'.'||c.callee,'call') detail,(c.callee_kind='identifier' AND c.callee IN "+helpers+") OR dynamic.id IS NOT NULL OR global.name IS NOT NULL allowed\n        FROM active_functions f JOIN calls c ON c.__path=f.__path AND c.__start>=f.body_start AND c.__end<=f.body_end LEFT JOIN dynamic_accesses dynamic ON dynamic.__path=c.__path AND dynamic.fn=f.id AND dynamic.id=c.id LEFT JOIN global_receivers global ON global.__path=c.__path AND global.fn=f.id AND global.id=c.receiver",('__path','fn','id')),
      S('attribute_events',"SELECT f.__path,f.id fn,a.id,a.__start,a.__end,'PLP-001' issue,a.attr detail,0 allowed FROM active_functions f JOIN attributes a ON a.__path=f.__path AND a.__start>=f.body_start AND a.__end<=f.body_end WHERE a.attr IN "+protected+" AND NOT (f.surface AND a.object_text='self' AND a.attr IN "+literals(value('PURE_SURFACE_CARRIER_ATTRS'))+") AND (f.strict OR EXISTS(SELECT 1 FROM protected_accesses p WHERE p.__path=a.__path AND p.fn=f.id AND p.id=a.id AND NOT p.through_call))"),
      S('global_events',"SELECT g.__path,g.fn,g.id,g.__start,g.__end,'PLP-009' issue,g.name detail,0 allowed FROM global_uses g WHERE g.mutable UNION ALL SELECT n.__path,g.fn,n.id,n.__start,n.__end,'PLP-009',g.name||'[]',0 FROM nodes n JOIN nodes value ON value.__path=n.__path AND value.parent=n.id AND value.ordinal=0 JOIN global_receivers g ON g.__path=value.__path AND g.id=value.id WHERE n.kind='subscript'"),
      S('events',"SELECT * FROM return_events WHERE issue IS NOT NULL OR allowed UNION ALL SELECT * FROM call_events WHERE issue IS NOT NULL OR allowed UNION ALL SELECT * FROM attribute_events UNION ALL SELECT * FROM global_events",('__path','fn')),
      S('visible_events',"SELECT e.* FROM events e JOIN active_functions f ON f.__path=e.__path AND f.id=e.fn WHERE e.issue IS NOT NULL AND (f.color='pure' OR e.issue IN ('PLP-001','PLP-002','PLP-003','PLP-004','PLP-005')) AND NOT EXISTS(SELECT 1 FROM events ancestor WHERE ancestor.__path=e.__path AND ancestor.fn=e.fn AND ancestor.id!=e.id AND ancestor.__start<=e.__start AND ancestor.__end>=e.__end) AND NOT EXISTS(SELECT 1 FROM calls cast_call JOIN arguments type ON type.__path=cast_call.__path AND type.call=cast_call.id AND type.position=0 WHERE cast_call.__path=e.__path AND cast_call.callee_kind='identifier' AND cast_call.callee='cast' AND (SELECT count(*) FROM arguments a WHERE a.__path=cast_call.__path AND a.call=cast_call.id)=2 AND type.__start<=e.__start AND type.__end>=e.__end)"),
      S('file_modules',"SELECT __path,replace(CASE WHEN __path GLOB '*/__init__.py' THEN substr(__path,1,length(__path)-12) ELSE substr(__path,1,length(__path)-3) END,'/','.') module FROM nodes WHERE kind='module'",('__path',)),
      S('export_names',"SELECT m.__path,m.module,coalesce(x.alias_source,x.name_source,x.text) name,n.module_name_source target_module,coalesce(x.name_source,x.text) target_name FROM file_modules m JOIN nodes n ON n.__path=m.__path AND n.kind='import_from_statement' JOIN nodes parent ON parent.__path=n.__path AND parent.id=n.parent AND parent.kind='module' JOIN nodes x ON x.__path=n.__path AND x.parent=n.id AND x.kind IN ('dotted_name','aliased_import') AND x.id IS NOT n.module_name_kind||':'||n.module_name_start||':'||n.module_name_end UNION ALL SELECT m.__path,m.module,f.name,NULL,NULL FROM file_modules m JOIN function_flags f ON f.__path=m.__path AND f.lexical_parent IS NULL",('module','name')),
      S('exported_functions',"""WITH RECURSIVE exported(module,name) AS (
        SELECT e.module,e.name FROM export_names e WHERE e.__path GLOB 'data_layer/*.py' AND NOT rx_matches(substr(e.__path,12),'/') AND e.name NOT GLOB '_*' AND (NOT EXISTS(SELECT 1 FROM module_bindings b WHERE b.__path=e.__path AND b.name='__all__') OR EXISTS(SELECT 1 FROM module_bindings b JOIN strings s ON s.__path=b.__path AND s.__start>=b.right_start AND s.__end<=b.right_end WHERE b.__path=e.__path AND b.name='__all__' AND s.value=e.name))
        UNION SELECT e.target_module,e.target_name FROM exported old JOIN export_names e ON e.module=old.module AND e.name=old.name WHERE e.target_module IS NOT NULL)
        SELECT DISTINCT f.__path,f.id,f.__start,f.__end FROM exported e JOIN file_modules m ON m.module=e.module JOIN function_flags f ON f.__path=m.__path AND f.name=e.name AND f.lexical_parent IS NULL WHERE f.name GLOB '*_lazy' AND f.name NOT GLOB '_*' AND NOT f.explicit AND (NOT EXISTS(SELECT 1 FROM primary_paths) OR f.__path IN (SELECT path FROM primary_paths))"""),
      S('diagnostics',"SELECT __path,__start,__end,issue,fn||':'||id identity,detail FROM visible_events UNION ALL SELECT f.__path,f.__start,f.__end,'PLP-006',f.id||':contract','contract' FROM active_functions f JOIN return_contracts c ON c.__path=f.__path AND c.id=f.id WHERE f.color='pure' UNION ALL SELECT __path,__start,__end,'PLP-007',id||':export','export' FROM exported_functions"),
    ]
    modules=next(stage for stage in stages if stage['name']=='file_modules')
    stages.remove(modules)
    graph=[modules,
      S('call_imports',"SELECT n.__path,own.fn,coalesce(x.alias_source,x.name_source,x.text) local,CASE WHEN substr(n.module_name_source,1,1)='.' THEN rx_replace(m.module||CASE WHEN n.__path GLOB '*/__init__.py' THEN '.__init__' ELSE '' END,'(?:\\.[^.]+){'||length(rx_extract(n.module_name_source,'^\\.*',0))||'}$','')||'.'||rx_replace(n.module_name_source,'^\\.+','') ELSE n.module_name_source END||'.'||coalesce(x.name_source,x.text) target FROM nodes n JOIN file_modules m ON m.__path=n.__path JOIN ownership own ON own.__path=n.__path AND own.id=n.id JOIN nodes x ON x.__path=n.__path AND x.parent=n.id AND x.kind IN ('dotted_name','aliased_import') AND x.id IS NOT n.module_name_kind||':'||n.module_name_start||':'||n.module_name_end WHERE n.kind='import_from_statement' UNION ALL SELECT n.__path,own.fn,coalesce(x.alias_source,rx_extract(coalesce(x.name_source,x.text),'^[^.]+',0)),coalesce(x.name_source,x.text) FROM nodes n JOIN ownership own ON own.__path=n.__path AND own.id=n.id JOIN nodes x ON x.__path=n.__path AND x.parent=n.id AND x.kind IN ('dotted_name','aliased_import') WHERE n.kind='import_statement'",('__path','local')),
      S('qualified_functions',"SELECT f.__path,f.id,m.module||'.'||f.qualname qualified FROM declaration_contexts f JOIN file_modules m ON m.__path=f.__path WHERE f.kind='function_definition'",('qualified',)),
      S('purity_call_edges',"SELECT e.__path,e.caller,e.__path target_path,e.target FROM call_edges e UNION SELECT c.__path,o.fn,t.__path,t.id FROM calls c JOIN ownership o ON o.__path=c.__path AND o.id=c.id LEFT JOIN nodes receiver ON receiver.__path=c.__path AND receiver.id=c.receiver JOIN call_imports imp ON imp.__path=c.__path AND imp.local=CASE WHEN c.callee_kind='identifier' THEN c.callee ELSE receiver.text END AND (imp.fn IS NULL OR imp.fn=o.fn) JOIN qualified_functions t ON t.qualified=imp.target||CASE WHEN c.callee_kind='attribute' THEN '.'||c.callee ELSE '' END WHERE (c.callee_kind='identifier' OR c.callee_kind='attribute' AND receiver.kind='identifier') AND NOT EXISTS(SELECT 1 FROM parameters p WHERE p.__path=c.__path AND p.fn=o.fn AND p.name=imp.local) AND NOT EXISTS(SELECT 1 FROM assignments a JOIN bound_names b ON b.__path=a.__path AND b.assignment=a.id WHERE a.__path=c.__path AND a.fn=o.fn AND b.name=imp.local) AND NOT EXISTS(SELECT 1 FROM nodes n WHERE n.__path=c.__path AND n.kind='lambda' AND n.__start<c.__start AND n.__end>=c.__end) AND NOT(imp.fn IS NULL AND EXISTS(SELECT 1 FROM call_imports local WHERE local.__path=imp.__path AND local.fn=o.fn AND local.local=imp.local))",('__path','caller')),
    ]
    index=next(i for i,stage in enumerate(stages) if stage['name']=='function_flags')
    stages[index:index]=graph
    strings=E(A(O(K('string'),K('concatenated_string')),P('STRING'),{'regex':r'''(?i)^[ru]*["']'''}),{'value':'capture.DECODED.text'},transform={'DECODED':{'substring':{'source':'$STRING','value':True,'startChar':0}}})
    item=clause('pure-runtime-state',stages,"SELECT __path path,__start start_byte,__end end_byte,issue,identity FROM diagnostics",{'strings':strings})
    item['relational'].pop('partitionBy',None)
    item['relational']['query']={'$option':'entryPoint','cases':{'scan_source':item['relational']['query']+" WHERE issue!='PLP-007'"},'default':item['relational']['query']}
    p['clauses'].append(item);return p
